const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    briefText: body.text || '',
    slackChannel: body.channel_id || $env.SLACK_DEFAULT_CHANNEL || '',
    slackUserId: body.user_id || '',
    wpBaseUrl: $env.WP_BASE_URL || 'http://host.docker.internal:10020',
    wpAuth: 'Basic ' + Buffer.from(($env.WP_USERNAME || '') + ':' + ($env.WP_APP_PASSWORD || '')).toString('base64'),
    anthropicKey: $env.ANTHROPIC_API_KEY || '',
    slackToken: $env.SLACK_BOT_TOKEN || '',
  }
}];

const config = $('Load Config').first().json;

const systemPrompt = `You are a WordPress content classifier and field extractor for Aera Technology.

Available content types (CPTs) and their required fields:

blog:
  endpoint: blog
  acf: { resource_card_title, resource_excerpt, resource_cta_text, blog_lead }
  notes: Primary blog post type. blog_lead is a 1-2 sentence intro shown below the title.

press-release:
  endpoint: press-release
  acf: { press_release_publication, resource_card_title, resource_excerpt }
  notes: Official company announcements. press_release_publication is the outlet name.

case-study:
  endpoint: case-study
  acf: { case_study_company_name, case_study_industry, case_study_type, case_study_business_problem, case_study_business_statement, resource_card_title, resource_excerpt }
  notes: Customer success stories.

whitepaper:
  endpoint: whitepaper
  acf: { resource_card_title, resource_excerpt }
  notes: Gated research reports.

news:
  endpoint: news
  acf: { resource_external_url, resource_card_title, resource_excerpt }
  notes: Third-party coverage. No body content — external URL required.

video:
  endpoint: video
  acf: { video_url, video_type, resource_card_title, resource_excerpt }
  notes: Video content. video_url is a YouTube/Vimeo embed URL.

podcast:
  endpoint: podcast
  acf: { podcast_video, podcast_type, resource_card_title, resource_excerpt }
  notes: Podcast episodes. podcast_video is the embed URL.

report:
  endpoint: report
  acf: { resource_external_url, resource_card_title, resource_excerpt }
  notes: Research reports. external URL if gated.

Return ONLY a valid JSON object (no markdown, no explanation) with this exact structure:
{
  "cpt": "<endpoint slug>",
  "title": "<post title>",
  "slug": "<url-friendly-slug>",
  "content": "<full HTML body content, use <p>, <h2>, <h3>, <ul>, <li> tags>",
  "excerpt": "<SEO meta description, ~155 chars>",
  "acf": { <only the relevant ACF fields for this CPT, omit others> },
  "reasoning": "<one sentence explaining CPT choice>"
}`;

const userMessage = 'Analyze this content brief and extract all fields:\n\n' + config.briefText;

return [{
  json: {
    ...config,
    claudeRequestBody: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 8192,
      system: systemPrompt,
      messages: [{ role: 'user', content: userMessage }]
    }
  }
}];

const raw = $input.first().json.content?.[0]?.text || '';
const config = $('Load Config').first().json;

// Strip markdown code fences if Claude wrapped the JSON
const cleaned = raw.replace(/^```(?:json)?\n?/i, '').replace(/\n?```$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude returned invalid JSON: ' + raw.substring(0, 200));
}

const cpt = parsed.cpt || 'blog';
const slug = (parsed.slug || '').replace(/^[a-z-]+\//, ''); // strip any CPT prefix

// Build WP REST API post body
const wpBody = {
  title: parsed.title || 'Untitled',
  slug,
  content: parsed.content || '',
  excerpt: parsed.excerpt || '',
  status: 'draft',
  acf: parsed.acf || {},
};

return [{
  json: {
    cpt,
    wpUrl: config.wpBaseUrl + '/wp-json/wp/v2/' + cpt,
    wpBody,
    wpBodyJson: JSON.stringify(wpBody),
    title: parsed.title,
    reasoning: parsed.reasoning || '',
    wpBaseUrl: config.wpBaseUrl,
    wpAuth: config.wpAuth,
    slackToken: config.slackToken,
    slackChannel: config.slackChannel,
  }
}];

const wpPost = $input.first().json;
const ctx = $('Parse Claude Response').first().json;

// Parse WP response — might have PHP warnings before the JSON
let post = wpPost;
if (typeof wpPost === 'string') {
  const idx = wpPost.indexOf('{');
  if (idx > 0) post = JSON.parse(wpPost.substring(idx));
}

const postId = post.id;
const postTitle = (post.title?.rendered || post.title || ctx.title || 'Draft').trim();
const wpAdminUrl = ctx.wpBaseUrl.replace('host.docker.internal', 'localhost');
const editLink = wpAdminUrl + '/wp-admin/post.php?post=' + postId + '&action=edit';
const previewLink = wpAdminUrl + '/?p=' + postId + '&preview=true';

const cptLabels = {
  blog: 'Blog', 'press-release': 'Press Release', 'case-study': 'Case Study',
  whitepaper: 'Whitepaper', news: 'News', video: 'Video', podcast: 'Podcast', report: 'Report'
};
const cptLabel = cptLabels[ctx.cpt] || ctx.cpt;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '\u2705 Draft Created', emoji: true }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: '*Title:*\n' + postTitle },
      { type: 'mrkdwn', text: '*Type:*\n' + cptLabel },
    ]
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: '_' + (ctx.reasoning || '') + '_' }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: '<' + editLink + '|Edit in WordPress>  ·  <' + previewLink + '|Preview>' }
  }
];

return [{
  json: {
    channel: ctx.slackChannel,
    slackToken: ctx.slackToken,
    text: 'Draft created: ' + postTitle,
    blocks
  }
}];
